mapper.select:
SELECT 'EDHR_WORK_TASK' AS source_id, LPAD(CAST(mes_pro_edhr_work_task.id AS CHAR),20,'0') AS row_order_key, CAST(mes_pro_edhr_work_task.id AS CHAR) AS business_id,
CONCAT('EDHR_WORK_TASK:', mes_pro_edhr_work_task.id) AS task_key, '批记录' AS task_type, 'eDHR工作任务' AS source,
CONVERT(CONCAT(CASE mes_pro_edhr_work_task.task_type WHEN 'FILL' THEN '请填写批记录' WHEN 'REVIEW' THEN '请复核批记录' WHEN 'APPROVE' THEN '请批准批记录' WHEN 'REWORK' THEN '请修改退回的批记录' WHEN 'ARCHIVE' THEN '请完成批记录归档' WHEN 'CLOSE' THEN '请关闭批记录' WHEN 'RELEASE_APPROVE' THEN '请完成上市放行审批' WHEN 'PQC_PRODUCTION_RELEASE' THEN '请完成 PQC 生产放行' WHEN 'DEVIATION_RECEIVE' THEN '请开展偏差调查' WHEN 'DEVIATION_CORRECT' THEN '请完成偏差纠正' WHEN 'DEVIATION_SIGN' THEN '请完成偏差签署' WHEN 'DEVIATION_APPROVE' THEN '请完成偏差质量审核' WHEN 'DEVIATION_CLOSE' THEN '请关闭偏差' WHEN 'RECORD_CHANGE_APPROVE' THEN '请审批记录变更' WHEN 'RECORD_CHANGE_CORRECTION' THEN '请补正记录变更' WHEN 'DOSSIER_COMPLETE' THEN '请补齐放行资料' WHEN 'PQC_RELEASE_CORRECTION' THEN '请补正生产放行资料' ELSE '任务类型未识别，请核实任务数据' END, CHAR(10), CONCAT('生产订单：', CASE WHEN NULLIF(TRIM(mes_pro_edhr_work_task.work_order_code), '') IS NULL THEN '生产订单编号缺失' ELSE TRIM(mes_pro_edhr_work_task.work_order_code) END, '｜批次：', CASE WHEN NULLIF(TRIM(mes_pro_edhr_work_task.batch_code), '') IS NULL THEN '批次编号缺失' ELSE TRIM(mes_pro_edhr_work_task.batch_code) END, CASE WHEN NULLIF(TRIM(mes_pro_edhr_work_task.process_name), '') IS NOT NULL AND mes_pro_edhr_work_task.task_type IN ('FILL','REVIEW','APPROVE','REWORK') THEN CONCAT('｜工序：', TRIM(mes_pro_edhr_work_task.process_name)) ELSE '' END)) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail, CASE WHEN EXISTS (SELECT 1 FROM mes_pro_edhr_batch_execution frozen WHERE frozen.id=mes_pro_edhr_work_task.batch_execution_id AND frozen.tenant_id=mes_pro_edhr_work_task.tenant_id AND frozen.deleted=0 AND frozen.status=15) AND mes_pro_edhr_work_task.task_type IN ('FILL','REVIEW','APPROVE','REWORK','ARCHIVE','CLOSE') THEN '批次冻结，暂不可处理' ELSE CASE mes_pro_edhr_work_task.status WHEN 'TODO' THEN '待处理' WHEN 'OVERDUE' THEN '已逾期' END END AS status_label, mes_pro_edhr_work_task.create_time AS created_at, COALESCE(mes_pro_edhr_work_task.due_time,mes_pro_edhr_work_task.overdue_at) AS due_at, mes_pro_edhr_work_task.task_type AS domain_task_type, mes_pro_edhr_work_task.action_url, CAST(mes_pro_edhr_work_task.batch_execution_id AS CHAR) AS batch_execution_id, CAST(mes_pro_edhr_work_task.batch_task_id AS CHAR) AS batch_task_id, CAST(mes_pro_edhr_work_task.execution_id AS CHAR) AS execution_id, mes_pro_edhr_work_task.business_scope_type, CAST(mes_pro_edhr_work_task.business_scope_id AS CHAR) AS business_scope_id, mes_pro_edhr_work_task.assignee_user_id AS owner_user_id, mes_pro_edhr_work_task.candidate_user_snapshot AS candidate_user_snapshot
FROM mes_pro_edhr_work_task
WHERE mes_pro_edhr_work_task.tenant_id = #{q.tenantId} AND mes_pro_edhr_work_task.deleted = 0 AND mes_pro_edhr_work_task.status IN ('TODO','OVERDUE')




AND ${correctionSql}

AND ${dossierSql}
 AND ${batchSql}
